cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill && python3 - <<'EOF'
import subprocess, re, collections
branches=["rachel","monica","phoebe","joey","chandler","ross"]
msgs={}
for b in branches:
    out=subprocess.check_output(["git","log","--format=###%H%n%B","origin/friend/"+b]).decode()
    for rec in out.split("###")[1:]:
        lines=rec.split("\n",1)
        sha=lines[0].strip(); body=lines[1] if len(lines)>1 else ""
        if "Friend-Message: 1" in body:
            m=re.search(r"Episode:\s*(\S+)",body)
            msgs[sha]=(b,m.group(1) if m else "?")
ep=collections.defaultdict(list)
for sha,(b,e) in msgs.items(): ep[e].append((sha,b))
for e in sorted(ep): print(e, len(ep[e]))
import json
json.dump({k:list(v) for k,v in msgs.items()}, open("/tmp/msgs.json","w"))
EOF

